insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 77: Princípios Fundamentais (CF/88)
-- -----------------------------------------------------------------------------
('CF/88 — art. 1º', 'A República Federativa do Brasil, formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal, constitui-se em Estado Democrático de Direito e tem como fundamentos: I - a soberania; II - a cidadania; III - a dignidade da pessoa humana; IV - os valores sociais do trabalho e da livre iniciativa; V - o pluralismo político. Parágrafo único. Todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente, nos termos desta Constituição.', '1988-10-05', 15, 77),
('CF/88 — art. 2º', 'São Poderes da União, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário.', '1988-10-05', 15, 77),
('CF/88 — art. 3º', 'Constituem objetivos fundamentais da República Federativa do Brasil: I - construir uma sociedade livre, justa e solidária; II - garantir o desenvolvimento nacional; III - erradicar a pobreza e a marginalização e reduzir as desigualdades sociais e regionais; IV - promover o bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e quaisquer outras formas de discriminação.', '1988-10-05', 15, 77),
('CF/88 — art. 4º', 'A República Federativa do Brasil rege-se nas suas relações internacionais pelos seguintes princípios: I - independência nacional; II - prevalência dos direitos humanos; III - autodeterminação dos povos; IV - não-intervenção; V - igualdade entre os Estados; VI - defesa da paz; VII - solução pacífica dos conflitos; VIII - repúdio ao terrorismo e ao racismo; IX - cooperação entre os povos para o progresso da humanidade; X - concessão de asilo político.', '1988-10-05', 15, 77),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 96: Segurança Pública (CF/88)
-- -----------------------------------------------------------------------------
('CF/88 — art. 144 (caput)', 'A segurança pública, dever do Estado, direito e responsabilidade de todos, é exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio, através dos seguintes órgãos: I - polícia federal; II - polícia rodoviária federal; III - polícia ferroviária federal; IV - polícias civis; V - polícias militares e corpos de bombeiros militares; VI - polícias penais federal, estaduais e distrital.', '1988-10-05', 15, 96),
('CF/88 — art. 144, § 1º', 'A polícia federal, instituída por lei como órgão permanente, organizado e mantido pela União e estruturado em carreira, destina-se a: I - apurar infrações penais contra a ordem política e social ou em detrimento de bens, serviços e interesses da União ou de suas entidades autárquicas e empresas públicas, assim como outras infrações cuja prática tenha repercussão interestadual ou internacional e exija repressão uniforme, segundo se dispuser em lei; II - prevenir e reprimir o tráfico ilícito de entorpecentes e drogas afins, o contrabando e o descaminho, sem prejuízo da ação fazendária e de outros órgãos públicos nas respectivas áreas de competência; III - exercer as funções de polícia marítima, aeroportuária e de fronteiras; IV - exercer, com exclusividade, as funções de polícia judiciária da União.', '1988-10-05', 15, 96),
('CF/88 — art. 144, § 2º', 'A polícia rodoviária federal, órgão permanente, organizado e mantido pela União e estruturado em carreira, destina-se, na forma da lei, ao patrulhamento ostensivo das rodovias federais.', '1988-10-05', 15, 96),
('CF/88 — art. 144, § 4º', 'Às polícias civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União, as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.', '1988-10-05', 15, 96),
('CF/88 — art. 144, § 5º', 'Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, incumbe a execução de atividades de defesa civil.', '1988-10-05', 15, 96),
('CF/88 — art. 144, § 5º-A', 'Às polícias penais, vinculadas ao órgão administrador do sistema penal da unidade federativa a que pertencem, cabe a segurança dos estabelecimentos penais.', '2019-12-04', 15, 96),
('CF/88 — art. 144, § 8º', 'Os Municípios poderão constituir guardas municipais destinadas à proteção de seus bens, serviços e instalações, conforme dispuser a lei.', '1988-10-05', 15, 96),

-- -----------------------------------------------------------------------------
-- DIREITO CONSTITUCIONAL (ID 15) — TÓPICO 78: Funções Essenciais à Justiça
-- -----------------------------------------------------------------------------
('CF/88 — art. 127 (caput)', 'O Ministério Público é instituição permanente, essencial à função jurisdicional do Estado, incumbindo-lhe a defesa da ordem jurídica, do regime democrático e dos interesses sociais e individuais indisponíveis.', '1988-10-05', 15, 78),
('CF/88 — art. 127, § 1º', 'São princípios institucionais do Ministério Público a unidade, a indivisibilidade e a independência funcional.', '1988-10-05', 15, 78),
('CF/88 — art. 129, I', 'São funções institucionais do Ministério Público: I - promover, privativamente, a ação penal pública, na forma da lei;', '1988-10-05', 15, 78),
('CF/88 — art. 129, II', 'São funções institucionais do Ministério Público: II - zelar pelo efetivo respeito dos Poderes Públicos e dos serviços de relevância pública aos direitos assegurados nesta Constituição, promovendo as medidas necessárias a sua garantia;', '1988-10-05', 15, 78),
('CF/88 — art. 129, III', 'São funções institucionais do Ministério Público: III - promover o inquérito civil e a ação civil pública, para a proteção do patrimônio público e social, do meio ambiente e de outros interesses difusos e coletivos;', '1988-10-05', 15, 78),
('CF/88 — art. 133', 'O advogado é indispensável à administração da justiça, sendo inviolável por seus atos e manifestações no exercício da profissão, nos limites da lei.', '1988-10-05', 15, 78),
('CF/88 — art. 134 (caput)', 'A Defensoria Pública é instituição permanente, essencial à função jurisdicional do Estado, incumbindo-lhe, como expressão e instrumento do regime democrático, fundamentalmente, a orientação jurídica, a promoção dos direitos humanos e a defesa, em todos os graus, judicial e extrajudicial, dos direitos individuais e coletivos, de forma integral e gratuita, aos necessitados.', '1988-10-05', 15, 78),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 503: Provimento e Regime Disciplinar (Lei nº 8.112/1990)
-- -----------------------------------------------------------------------------
('Lei nº 8.112/1990 — art. 5º', 'São requisitos básicos para investidura em cargo público: I - a nacionalidade brasileira; II - o gozo dos direitos políticos; III - a quitação com as obrigações militares e eleitorais; IV - o nível de escolaridade exigido para o exercício do cargo; V - a idade mínima de dezoito anos; VI - aptidão física e mental.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 8º', 'São formas de provimento de cargo público: I - nomeação; II - promoção; V - readaptação; VI - reversão; VII - aproveitamento; VIII - reintegração; IX - recondução.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 13 (caput)', 'A posse dar-se-á pela assinatura do respectivo termo, no qual deverão constar as atribuições, os deveres, as responsabilidades e os direitos inerentes ao cargo ocupado, que não poderão ser alterados unilateralmente, por qualquer das partes, ressalvados os atos de ofício previstos em lei.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 13, § 1º', 'A posse ocorrerá no prazo de trinta dias contados da publicação do ato de provimento.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 13, § 6º', 'Será tornado sem efeito o ato de provimento se a posse não ocorrer no prazo previsto no § 1º deste artigo.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 15, § 1º', 'É de quinze dias o prazo para o servidor empossado em cargo público entrar em exercício, contados da data da posse.', '1997-12-10', 14, 503),
('Lei nº 8.112/1990 — art. 15, § 2º', 'O servidor será exonerado do cargo ou será tornado sem efeito o ato de sua designação para função de confiança, se não entrar em exercício no prazo previsto no parágrafo anterior.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 20 (caput)', 'Ao entrar em exercício, o servidor nomeado para cargo de provimento efetivo ficará sujeito a estágio probatório por período de 24 (vinte e quatro) meses, durante o qual a sua aptidão e capacidade serão objeto de avaliação para o desempenho do cargo, observados os seguinte fatores: I - assiduidade; II - disciplina; III - capacidade de iniciativa; IV - produtividade; V- responsabilidade.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 21', 'O servidor habilitado em concurso público e empossado em cargo de provimento efetivo adquirirá estabilidade no serviço público ao completar 3 (três) anos de efetivo exercício.', '1998-06-04', 14, 503),
('Lei nº 8.112/1990 — art. 24', 'Readaptação é a investidura do servidor em cargo de atribuições e responsabilidades compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental verificada em inspeção médica.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 25', 'Reversão é o retorno à atividade de servidor aposentado: I - por invalidez, quando junta médica oficial declarar insubsistentes os motivos da aposentadoria; ou II - no interesse da administração, desde que: a) tenha solicitado a reversão; b) a aposentadoria tenha sido voluntária; c) estável quando na atividade; d) a aposentadoria tenha ocorrido nos cinco anos anteriores à solicitação; e) haja cargo vago.', '1997-12-10', 14, 503),
('Lei nº 8.112/1990 — art. 28', 'A reintegração é a reinvestidura do servidor estável no cargo anteriormente ocupado, ou no cargo resultante de sua transformação, quando invalidada a sua demissão por decisão administrativa ou judicial, com ressarcimento de todas as vantagens.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 29', 'Recondução é o retorno do servidor estável ao cargo anteriormente ocupado e decorrerá de: I - inabilitação em estágio probatório relativo a outro cargo; II - reintegração do anterior ocupante. Parágrafo único. Encontrando-se provido o cargo de origem, o servidor será aproveitado em outro, observado o disposto no art. 30.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 33', 'A vacância do cargo público decorrerá de: I - exoneração; II - demissão; III - promoção; VI - readaptação; VII - aposentadoria; VIII - posse em outro cargo inacumulável; IX - falecimento.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 127', 'São penalidades disciplinares: I - advertência; II - suspensão; III - demissão; IV - cassação de aposentadoria ou disponibilidade; V - destituição de cargo em comissão; VI - destituição de função comissionada.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 128', 'Na aplicação das penalidades serão consideradas a natureza e a gravidade da infração cometida, os danos que dela provierem para o serviço público, as circunstâncias agravantes ou atenuantes e os antecedentes funcionais.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 130', 'A suspensão será aplicada em caso de reincidência das faltas punidas com advertência e de violação das demais proibições que não tipifiquem infração sujeita a penalidade de demissão, não podendo exceder de 90 (noventa) dias.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 132', 'A demissão será aplicada nos seguintes casos: I - crime contra a administração pública; II - abandono de cargo; III - inassiduidade habitual; IV - improbidade administrativa; V - incontinência pública e conduta escandalosa, na repartição; VI - insubordinação grave em serviço; VII - ofensa física, em serviço, a servidor ou a particular, salvo em legítima defesa própria ou de outrem; VIII - aplicação irregular de dinheiros públicos; IX - revelação de segredo do qual se apropriou em razão do cargo; X - lesão aos cofres públicos e dilapidação do patrimônio nacional; XI - corrupção; XII - acumulação ilegal de cargos, empregos ou funções públicas; XIII - transgressão dos incisos IX a XVI do art. 117.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 138', 'Configura abandono de cargo a ausência intencional do servidor ao serviço por mais de trinta dias consecutivos.', '1990-12-11', 14, 503),
('Lei nº 8.112/1990 — art. 139', 'Entende-se por inassiduidade habitual a falta ao serviço, sem causa justificada, por sessenta dias, interpoladamente, durante o período de doze meses.', '1997-12-10', 14, 503),
('Lei nº 8.112/1990 — art. 142', 'A ação disciplinar prescreverá: I - em 5 (cinco) anos, quanto às infrações puníveis com demissão, cassação de aposentadoria ou disponibilidade e destituição de cargo em comissão; II - em 2 (dois) anos, quanto à suspensão; III - em 180 (cento e oitenta) dias, quanto à advertência. § 1º O prazo de prescrição começa a correr da data em que o fato se tornou conhecido.', '1990-12-11', 14, 503),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 95: Licitações (Lei nº 14.133/2021)
-- -----------------------------------------------------------------------------
('Lei nº 14.133/2021 — art. 5º', 'Na aplicação desta Lei, serão observados os princípios da legalidade, da impessoalidade, da moralidade, da publicidade, da eficiência, do interesse público, da probidade administrativa, da igualdade, do planejamento, da transparência, da eficácia, da segregação de funções, da motivação, da vinculação ao edital, do julgamento objetivo, da segurança jurídica, da razoabilidade, da competitividade, da proporcionalidade, da celeridade, da economicidade e do desenvolvimento nacional sustentável.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 28', 'São modalidades de licitação: I - pregão; II - concorrência; III - concurso; IV - leilão; V - diálogo competitivo. § 1º É vedada a criação de outras modalidades de licitação ou a combinação das referidas neste artigo.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 29', 'A concorrência e o pregão seguem o rito procedimental comum a que se refere o art. 17 desta Lei, adotando-se o pregão sempre que o objeto possuir padrões de desempenho e qualidade que possam ser objetivamente definidos pelo edital, por meio de especificações usuais de mercado.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 74 (caput)', 'É inexigível a licitação quando inviável a competição, em especial nos casos de: I - aquisição de materiais, de equipamentos ou de gêneros ou contratação de serviços que só possam ser fornecidos por produtor, empresa ou representante comercial exclusivos; II - contratação de profissional do setor artístico, diretamente ou por meio de empresário exclusivo, desde que consagrado pela crítica especializada ou pela opinião pública; III - contratação dos seguintes serviços técnicos especializados de natureza predominantemente intelectual com profissionais ou empresas de notória especialização.', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 75, I', 'É dispensável a licitação: I - para contratação que envolva valores inferiores a R$ 100.000,00 (cem mil reais), no caso de obras e serviços de engenharia ou de serviços de manutenção de veículos automotores;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 75, II', 'É dispensável a licitação: II - para contratação que envolva valores inferiores a R$ 50.000,00 (cinquenta mil reais), no caso de outros serviços e compras;', '2021-04-01', 14, 95),
('Lei nº 14.133/2021 — art. 75, VIII', 'É dispensável a licitação: VIII - nos casos de emergência ou de calamidade pública, quando caracterizada urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a continuidade dos serviços públicos ou a segurança de pessoas, obras, serviços, equipamentos e outros bens.', '2021-04-01', 14, 95),

-- -----------------------------------------------------------------------------
-- DIREITO ADMINISTRATIVO (ID 14) — TÓPICO 201: Anulação e Revogação (Lei nº 9.784/1999)
-- -----------------------------------------------------------------------------
('Lei nº 9.784/1999 — art. 53', 'A Administração deve anular seus próprios atos, quando eivados de vício de legalidade, e pode revogá-los por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 54 (caput)', 'O direito da Administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em cinco anos, contados da data em que foram praticados, salvo comprovada má-fé.', '1999-01-29', 14, 201),
('Lei nº 9.784/1999 — art. 55', 'Em decisão na qual se evidencie não acarretarem lesão ao interesse público nem prejuízo a terceiros, os atos que apresentarem defeitos sanáveis poderão ser convalidados pela própria Administração.', '1999-01-29', 14, 201),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO PENAL ESPECIAL (ID 19) — TÓPICO 50: Abuso de Autoridade (Lei nº 13.869/2019)
-- -----------------------------------------------------------------------------
('Lei nº 13.869/2019 — art. 1º, § 1º', 'As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal.', '2019-09-05', 19, 50),
('Lei nº 13.869/2019 — art. 1º, § 2º', 'A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade.', '2019-09-05', 19, 50),
('Lei nº 13.869/2019 — art. 2º', 'É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território.', '2019-09-05', 19, 50),
('Lei nº 13.869/2019 — art. 3º', 'Os crimes previstos nesta Lei são de ação penal pública incondicionada. § 1º Será admitida ação privada se a ação penal pública não for intentada no prazo legal, aplicando-se o disposto no art. 29 do Código de Processo Penal.', '2019-09-05', 19, 50),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO PENAL ESPECIAL (ID 19) — TÓPICO 52: Lei de Drogas (Lei nº 11.343/2006)
-- -----------------------------------------------------------------------------
('Lei nº 11.343/2006 — art. 28 (caput)', 'Quem adquirir, guardar, tiver em depósito, transportar ou trouxer consigo, para consumo pessoal, drogas sem autorização ou em desacordo com determinação legal ou regulamentar será submetido às seguintes penas: I - advertência sobre os efeitos das drogas; II - prestação de serviços à comunidade; III - medida educativa de comparecimento a programa ou curso educativo.', '2006-08-23', 19, 52),
('Lei nº 11.343/2006 — art. 28, § 2º', 'Para determinar se a droga destinava-se a consumo pessoal, o juiz atenderá à natureza e à quantidade da substância apreendida, ao local e às condições em que se desenvolveu a ação, às circunstâncias sociais e pessoais, bem como à conduta e aos antecedentes do agente.', '2006-08-23', 19, 52),
('Lei nº 11.343/2006 — art. 33 (caput)', 'Importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer drogas, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar: Pena - reclusão de 5 a 15 anos e pagamento de 500 a 1.500 dias-multa.', '2006-08-23', 19, 52),
('Lei nº 11.343/2006 — art. 33, § 4º', 'Nos delitos definidos no caput e no § 1º deste artigo, as penas poderão ser reduzidas de um sexto a dois terços, desde que o agente seja primário, de bons antecedentes, não se dedique às atividades criminosas nem integre organização criminosa (tráfico privilegiado).', '2006-08-23', 19, 52),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO PENAL ESPECIAL (ID 19) — TÓPICO 90: Crimes Hediondos (Lei nº 8.072/1990)
-- -----------------------------------------------------------------------------
('Lei nº 8.072/1990 — art. 1º (caput)', 'São considerados hediondos os seguintes crimes, todos tipificados no Decreto-Lei no 2.848, de 7 de dezembro de 1940 - Código Penal, consumados ou tentados: I - homicídio, quando praticado em atividade típica de grupo de extermínio, ainda que cometido por um só agente, e homicídio qualificado; I-A - lesão corporal dolosa de natureza gravíssima e lesão corporal seguida de morte, quando praticadas contra autoridade ou agente de segurança pública; II - roubo circunstanciado ou qualificado; III - extorsão qualificada pela restrição da liberdade da vítima, ocorrência de lesão corporal ou morte; IV - extorsão mediante seqüestro e na forma qualificada; V - estupro; VI - estupro de vulnerável; VII - epidemia com resultado morte; VII-B - falsificação, corrupção, adulteração ou alteração de produto destinado a fins terapêuticos ou medicinais; VIII - favorecimento da prostituição ou de outra forma de exploração sexual de criança ou adolescente ou de vulnerável; IX - furto qualificado pelo emprego de explosivo ou de artefato análogo que cause perigo comum.', '1990-07-25', 19, 90),
('Lei nº 8.072/1990 — art. 2º', 'Os crimes hediondos, a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins e o terrorismo são insuscetíveis de: I - anistia, graça e indulto; II - fiança.', '1990-07-25', 19, 90),

-- -----------------------------------------------------------------------------
-- ÉTICA NO SERVIÇO PÚBLICO (ID 20) — TÓPICO 430: Ética no Serviço Público Federal (Decreto nº 1.171/1994)
-- -----------------------------------------------------------------------------
('Decreto nº 1.171/1994 — Seção I, Regra I', 'A dignidade, o decoro, o zelo, a eficácia e a consciência dos princípios morais são primados maiores que devem nortear o servidor público, seja no exercício do cargo ou função, ou fora dele, já que refletirá o exercício da vocação do próprio poder estatal.', '1994-06-22', 20, 430),
('Decreto nº 1.171/1994 — Seção I, Regra II', 'O servidor público não poderá jamais desprezar o elemento ético de sua conduta. Assim, não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto.', '1994-06-22', 20, 430),
('Decreto nº 1.171/1994 — Seção I, Regra III', 'A moralidade da Administração Pública não se limita à distinção entre o bem e o mal, devendo ser acrescida da idéia de que o fim é sempre o bem comum. O equilíbrio entre a legalidade e a finalidade, na conduta do servidor público, é que poderá consolidar a moralidade do ato administrativo.', '1994-06-22', 20, 430),
('Decreto nº 1.171/1994 — Seção I, Regra VII', 'O servidor não pode omitir a verdade, ainda que contrária aos interesses da própria pessoa interessada ou da Administração Pública. Nenhum Estado pode crescer ou estabilizar-se sobre o poder corruptivo do hábito do erro, da opressão ou da mentira.', '1994-06-22', 20, 430),
('Decreto nº 1.171/1994 — Seção I, Regra VIII', 'Toda pessoa tem direito à verdade. O servidor não pode falseá-la ou omiti-la, ainda que contrária aos interesses da própria pessoa interessada ou da Administração Pública.', '1994-06-22', 20, 430),
('Decreto nº 1.171/1994 — Seção I, Regra IX', 'A publicidade dos atos administrativos constitui requisito de eficácia e moralidade, ensejando sua omissão comprometimento ético contra o bem comum, imputável a quem a negar, ressalvados os casos de segurança nacional, investigações policiais ou interesse superior da Administração.', '1994-06-22', 20, 430)

on conflict (referencia) do update set 
    texto = excluded.texto, 
